lab.solution:
class FakeStore:
    def __init__(self):
        self.items = []

    def save_completion(self, learner_id, lesson_id):
        self.items.append((learner_id, lesson_id))

def mark_complete(store, learner_id, lesson_id):
    if not learner_id or not lesson_id:
        raise ValueError('both IDs are required')
    store.save_completion(learner_id, lesson_id)
    return {'ok': True, 'lesson_id': lesson_id}

fake = FakeStore()
assert mark_complete(fake, 'ana', 'loops') == {'ok': True, 'lesson_id': 'loops'}
assert fake.items == [('ana', 'loops')]

lab.testCode:
fake=FakeStore()
assert mark_complete(fake,'ana','loops')=={'ok':True,'lesson_id':'loops'}
assert fake.items==[('ana','loops')]
try: mark_complete(fake,'ana','')
except ValueError: pass
else: raise AssertionError('missing lesson accepted')
assert len(fake.items)==1
print('PASS: injected store boundary')
